export const BODY: string = "\n<p>AVIF هي أحدث صيغة صور على الويب، وأيضًا الصيغة التي لا تستطيع معظم التطبيقات فتحها. إنها صغيرة جدًا، لكن توافقها محدود.</p>\n<p>تحويل AVIF إلى JPG هو الحل. النتيجة تُفتح في كل مكان، من حاسوب قديم إلى بوابة توظيف إلى طابعة.</p>\n<p>يشرح هذا الدليل ما AVIF، ولماذا توجد، وكيف تحوّلها بنظافة.</p>\n<h2 id=\"what-is-avif\">ما AVIF؟</h2>\n<p>ما AVIF؟ صيغة صور حديثة مبنية على ضغط فيديو AV1 المتقدم. أصغر من JPG وWebP بالجودة نفسها، وتدعم الشفافية وHDR.</p>\n<p>AVIF هي مستقبل صور الويب، لكنها حديثة جدًا. كثير من التطبيقات والأنظمة لا تدعمها بعد.</p>\n<h2 id=\"why-websites-use-avif\">لماذا تخدم المواقع الحديثة AVIF؟</h2>\n<p>لماذا تخدم المواقع الحديثة AVIF؟ لأنها أصغر بكثير من JPG وWebP. الصفحات الأسرع تعني زوارًا أكثر سعادة وترتيبًا أفضل.</p>\n<p>المواقع الحديثة تستخدم AVIF لتوفير النطاق الترددي. التوفير يتراكم عبر آلاف الصور.</p>\n<h2 id=\"why-apps-reject-avif\">لماذا ترفض التطبيقات والنماذج AVIF؟</h2>\n<p>لماذا ترفض التطبيقات والنماذج AVIF؟ لأن AVIF حديثة جدًا، والتطبيقات والبوابات القديمة لا تعرفها. التحويل إلى JPG هو الحل العملي.</p>\n<p>حتى بعض التطبيقات الحديثة لا تدعم AVIF في كل مكان. التوافق الكامل هو سبب التحويل.</p>\n<h2 id=\"how-decoding-works\">كيف يعمل فك تشفير AVIF في المتصفح؟</h2>\n<p>كيف يعمل فك تشفير AVIF في المتصفح؟ المتصفح يقرأ ملف AVIF ويفك ضغطه إلى بكسلات، ثم يعيد ترميزها كـJPG. كل ذلك يحدث على جهازك.</p>\n<p>فك تشفير AVIF يحتاج إلى معالجة أكثر من الصيغ الأخرى، لذلك قد يستغرق التحويل وقتًا أطول قليلًا. لكن النتيجة تستحق الانتظار.</p>\n<h2 id=\"quality-settings\">إعدادات الجودة التي تعمل</h2>\n<p>إعدادات الجودة التي تعمل: جودة 90 مناسبة لمعظم الصور، و85 للمشاركة اليومية. جودة 95 للصور المهمة التي تحتاج إلى أقصى حدة.</p>\n<p>لا تستخدم جودة أقل من 80 للصور فيها نصوص. النص يضبب بسرعة عند الجودة المنخفضة.</p>\n<h2 id=\"file-size-after\">لماذا ملف JPG أكبر من AVIF؟</h2>\n<p>لماذا ملف JPG أكبر من AVIF؟ لأن JPG أقل كفاءة في الضغط من AVIF. الصورة نفسها تحتاج مساحة أكبر بصيغة JPG.</p>\n<p>هذا طبيعي وليس خطأ. أنت تستبدل الكفاءة بالتوافق، والملف الأكبر هو ثمن فتح الصورة في كل مكان.</p>\n<h2 id=\"transparency-handling\">الشفافية في تحويل AVIF</h2>\n<p>الشفافية في تحويل AVIF: عندما تحوّل صورة شفافة إلى JPG، تُملأ المناطق الشفافة بلون تختاره، عادة أبيض. اختر لونًا يطابق خلفية الوجهة.</p>\n<p>وللتحويل إلى صيغ أخرى تحافظ على الشفافية، جرّب <a href=\"/ar/tahwil-as-suwar/\">محول الصور</a>.</p>\n<h2 id=\"hdr-and-colour\">صور HDR والنطاق الواسع</h2>\n<p>صور HDR والنطاق الواسع: AVIF تدعم HDR والألوان الواسعة، وJPG لا يدعمها بالكامل. التحويل إلى JPG قد يفقد بعض حيوية الألوان.</p>\n<p>إذا كانت صورتك HDR، فتوقع تغيرًا طفيفًا في الألوان بعد التحويل. هذا ثمن التوافق مع الأنظمة القديمة.</p>\n<h2 id=\"batch-converting\">تحويل دفعات من تنزيلات AVIF</h2>\n<p>لتحويل دفعات من تنزيلات AVIF، ارفع كل الملفات وحوّلها بإعدادات موحدة. الأداة تحوّل الدفعة كاملة وتنزّلها كملف ZIP.</p>\n<p>راجع عينة من النتائج قبل الاعتماد على الدفعة كلها. إذا بدت العينة جيدة، فغالبًا بقية الصور بنفس الجودة.</p>\n<h2 id=\"checking-quality\">مراجعة الجودة قبل التنزيل</h2>\n<p>مراجعة الجودة قبل التنزيل: قارن النتيجة بالأصل، وتأكد من أن الألوان صحيحة والنص حاد ولون الخلفية مناسب.</p>\n<p>كبّر الصورة وافحص التفاصيل الدقيقة. إذا بدت النتيجة جيدة مكبّرة، فهي جاهزة للاستخدام.</p>\n<h2 id=\"avif-vs-jpg-decision\">متى تحتفظ بـAVIF؟</h2>\n<p>متى تحتفظ بـAVIF؟ عندما تنشر على موقع إلكتروني حديث يدعم AVIF. الحجم الأصغر يعني صفحات أسرع وزوارًا أكثر سعادة.</p>\n<p>احتفظ بـAVIF للأرشيف أيضًا. الأصل AVIF هو مصدر كل نسخة مستقبلية بجودة عالية.</p>\n<h2 id=\"common-problems\">مشاكل شائعة وحلولها</h2>\n<p>مشاكل شائعة وحلولها: ملف يفشل في التحويل قد يكون تالفًا أو متصفحك قديمًا لا يدعم AVIF. حدّث متصفحك أولًا.</p>\n<p>إذا ظهرت الألوان باهتة بعد التحويل، فأعد التحويل بجودة أعلى. صور HDR قد تفقد بعض حيويتها في JPG.</p>\n<h2 id=\"avif-from-news-sites\">صور AVIF من مواقع الأخبار</h2>\n<p>صور AVIF من مواقع الأخبار: كثير من مواقع الأخبار تخدم صور AVIF. حوّلها إلى JPG قبل استخدامها في تطبيقات أو مستندات لا تدعم AVIF.</p>\n<p>التحويل المسبق يمنع مفاجآت يوم الاستخدام. تحقق من أن كل صورة تفتح بشكل صحيح قبل الاعتماد عليها.</p>\n<h2 id=\"avif-for-work\">صور AVIF للعمل</h2>\n<p>صور AVIF للعمل: بعض برامج العمل لا تقبل AVIF. حوّل الصور إلى JPG قبل إدراجها في مستندات أو عروض تقديمية.</p>\n<p>التحويل المسبق يمنع مفاجآت يوم العرض. تحقق من أن كل صورة في مستندك تفتح بشكل صحيح قبل الاجتماع.</p>\n<h2 id=\"avif-for-printing\">صور AVIF للطباعة</h2>\n<p>صور AVIF للطباعة: معظم خدمات الطباعة والطابعات لا تقبل AVIF مباشرة. حوّل الصور إلى JPG قبل الطباعة.</p>\n<p>اطبع من ملف JPG المحوّل بجودة عالية. الطباعة تحتاج دقة كاملة، لذلك استخدم جودة 95 للصور التي ستطبعها.</p>\n<h2 id=\"avif-for-social-media\">صور AVIF لوسائل التواصل</h2>\n<p>صور AVIF لوسائل التواصل: معظم المنصات تحوّل الصور تلقائيًا، لكن AVIF قد يُرفض في بعض المنصات. حوّل إلى JPG قبل الرفع إذا لم تكن متأكدًا.</p>\n<p>إذا لم تكن متأكدًا من دعم المنصة، فاستخدم JPG. المنصات تقبل JPG دائمًا دون مشاكل.</p>\n<h2 id=\"keeping-avif-originals\">الاحتفاظ بأصول AVIF بعد التحويل</h2>\n<p>للاحتفاظ بأصول AVIF بعد التحويل، احتفظ بالملفات الأصلية في مجلد منفصل. الأصل هو مصدر كل نسخة مستقبلية.</p>\n<p>وللخطوات العملية، استخدم <a href=\"/ar/tahwil-avif-ila-jpg/\">محول AVIF إلى JPG</a>، واقرأ <a href=\"/ar/blog/kayfiyya-tahwil-avif-ila-jpg/\">كيفية تحويل AVIF إلى JPG</a> و<a href=\"/ar/blog/avif-vs-jpg/\">AVIF مقابل JPG</a>، أو جرّب <a href=\"/ar/tahwil-as-suwar/\">محول الصور</a> لصيغ أخرى.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما AVIF ولماذا لا تستطيع بعض التطبيقات فتحه؟","answer":"AVIF هي أحدث صيغة صور على الويب، مبنية على ضغط فيديو متقدم. أصغر من JPG بكثير، لكن كثير من التطبيقات لا تدعمها بعد."},{"question":"ما المتصفحات التي تستطيع فك تشفير AVIF للتحويل؟","answer":"معظم المتصفحات الحديثة تستطيع فك تشفير AVIF: كروم وفايرفوكس وسفاري الحديث. إذا كان متصفحك قديمًا، فحدّثه أولًا."},{"question":"هل تحويل AVIF إلى JPG يفقد الجودة؟","answer":"فقدان الجودة ضئيل جدًا عند جودة 90. التحويل من AVIF إلى JPG يحافظ على التفاصيل، ومعظم العيون لا تلاحظ أي فرق."},{"question":"هل ستصبح المناطق الشفافة في AVIF سوداء في JPG؟","answer":"لا، المناطق الشفافة تُملأ بلون الخلفية الذي تختاره، عادة أبيض. لن تصبح سوداء إذا اخترت لون تعبئة مناسبًا."},{"question":"ما أكبر ملف AVIF مقبول؟","answer":"الحد الأقصى يعتمد على متصفحك وذاكرته، لكن معظم الأدوات تقبل ملفات حتى 20 ميغابايت. الملفات الأكبر قد تحتاج إلى تقسيم."},{"question":"لماذا يكون ملف JPG أحيانًا أكبر من AVIF؟","answer":"لأن JPG أقل كفاءة في الضغط من AVIF. الصورة نفسها تحتاج مساحة أكبر بصيغة JPG، وهذا طبيعي وليس خطأ."}];
